 var phone=UnityEngine.Object.FindFirstObjectByType<PhoneController>();var planner=UnityEngine.Object.FindFirstObjectByType<NavigationPlanner>();var bikes=UnityEngine.Object.FindObjectsByType<MotorcycleController>(FindObjectsSortMode.None);foreach(var b in bikes)b.isDriven=false;phone.ClosePhone();int map=0,ui=0;void Count(ScriptableRenderContext context,Camera c){if(c.name=="NavigationCamera")map++;if(c.name=="NavigationUICamera")ui++;}RenderPipelineManager.endCameraRendering+=Count;
 try{float until=Time.unscaledTime+.6f;while(Time.unscaledTime<until)yield return null;map=ui=0;until=Time.unscaledTime+.6f;while(Time.unscaledTime<until)yield return null;Check(map==0&&ui==0,"Hidden phone stops both render cameras");
