 planner.Show(NavigationPlanner.Screen.Destinations);yield return null;map=ui=0;until=Time.unscaledTime+1.2f;while(Time.unscaledTime<until)yield return null;Check(map>0&&ui>0&&map<=38&&ui<=38,"Map opens and redraws at capped cadence");
 phone.ClosePhone();var cargo=UnityEngine.Object.FindObjectsByType<BikePizzaStorage>(FindObjectsSortMode.None).First(s=>s.bikeController!=null);cargo.bikeController.isDriven=true;Check(RobberAI.RiddenCargo==cargo,"Robbery detects mounted cargo");cargo.bikeController.isDriven=false;Check(RobberAI.RiddenCargo==null,"Dismount is visible within same frame");cargo.bikeController.isDriven=true;planner.Show(NavigationPlanner.Screen.Map);map=ui=0;until=Time.unscaledTime+.7f;while(Time.unscaledTime<until)yield return null;Check(map>0&&ui>0,"Mounted navigation remains rendered with handheld closed");cargo.bikeController.isDriven=false;
 }finally{RenderPipelineManager.endCameraRendering-=Count;phone.ClosePhone();foreach(var b in bikes)b.isDriven=false;}
 Check(SceneActors.Cargo.OrderBy(x=>x.GetInstanceID()).SequenceEqual(UnityEngine.Object.FindObjectsByType<BikePizzaStorage>(FindObjectsSortMode.InstanceID)),"Cargo registry matches scene query");
 var testObject=new GameObject("Registry regression temporary");testObject.SetActive(false);var extra=testObject.AddComponent<BikePizzaStorage>();extra.enabled=false;
 Check(!SceneActors.Cargo.Contains(extra),"Inactive new cargo excluded");testObject.SetActive(true);Check(SceneActors.Cargo.Contains(extra),"New cargo registered immediately, disabled component still discoverable");testObject.SetActive(false);Check(!SceneActors.Cargo.Contains(extra),"Deactivation visible in same frame");testObject.SetActive(true);Check(SceneActors.Cargo.Contains(extra),"Reactivation visible in same frame");UnityEngine.Object.DestroyImmediate(testObject);Check(!SceneActors.Cargo.Contains(extra),"Destroyed cargo removed");
 var policeObject=new GameObject("Registry police regression temporary");var officer=policeObject.AddComponent<PoliceControl>();officer.enabled=false;Check(SceneActors.Police.Contains(officer),"New officer registered immediately");policeObject.SetActive(false);Check(!SceneActors.Police.Contains(officer),"Inactive officer excluded immediately");UnityEngine.Object.DestroyImmediate(policeObject);
 var carried=UnityEngine.Object.FindFirstObjectByType<CarriedItemVisual>();yield return null;Check(carried!=null&&carried.OverlayCamera!=null&&!carried.OverlayCamera.enabled,"Empty hands stop overlay camera");
 var inv=carried.GetComponent<ToppingInventory>();inv.AddPackagedDataStack(new System.Collections.Generic.List<PizzaData>{new PizzaData(new System.Collections.Generic.List<string>{"치즈"},true)});yield return null;Check(carried.Display!=null&&carried.OverlayCamera.enabled,"Holding a pizza box resumes original overlay rendering");inv.ClearPackagedPizzas();yield return null;Check(!carried.OverlayCamera.enabled,"Putting the box down stops overlay again");
 var cars=UnityEngine.Object.FindObjectsByType<CarMov>(FindObjectsSortMode.None);Check(cars.Length==74,"All 74 moving cars retained");var positions=cars.Select(c=>c.transform.position).ToArray();float end=Time.time+2;while(Time.time<end)yield return null;Check(cars.Where((c,i)=>Vector3.Distance(c.transform.position,positions[i])>.1f).Count()>40,"Traffic continues moving in all districts");
 foreach(var test in new[]{WeaponNavigationTest.RunCore(log),WeaponTest.RunCore(log),TravelTimeTest.RunCore(log),RatingOrdersTest.RunCore(log),BikeRobberTest.RunCore(log)})while(test.MoveNext())yield return test.Current;
